<?php $groups=[];foreach($settings as $s)$groups[$s['group']][]=$s; ?>
<section class="page-header"><div><span class="eyebrow">System administration</span><h1>Settings</h1><p>Company, numbering, tax, office, attendance, integrations and backups.</p></div><div class="page-actions"><a class="button button-secondary" href="<?= url('settings/roles') ?>"><i class="fa-solid fa-shield-halved"></i> Permission matrix</a></div></section>
<form method="post" action="<?= url('settings') ?>"><?= csrf_field() ?><div class="settings-layout"><nav class="panel settings-nav"><a href="#company" class="active">Company profile</a><a href="#numbering">Numbering</a><a href="#tax">Tax & finance</a><a href="#location">Office & geofence</a><a href="#attendance-rules">Attendance rules</a><a href="#notifications">Notifications</a><a href="#backups">Database backups</a></nav><div class="settings-content">
<?php foreach($groups as $group=>$items):?><section class="panel settings-section" id="<?= e($group) ?>"><div class="panel-head"><div><h2><?= e(ucwords(str_replace('_',' ',$group))) ?></h2><p>Configure <?= e($group) ?> defaults</p></div></div><div class="form-grid"><?php foreach($items as $setting):?><label><?= e(ucwords(str_replace('_',' ',$setting['key']))) ?><input name="settings[<?= e($setting['key']) ?>]" value="<?= e($setting['value']) ?>" <?= str_contains($setting['key'],'password')?'type="password"':'' ?>></label><?php endforeach;?></div></section><?php endforeach;?>
<section class="panel settings-section" id="location"><div class="panel-head"><div><h2>Office & geofence</h2><p>Coordinates and permitted punch radius</p></div></div><input type="hidden" name="office_id" value="<?= (int)($office['id']??0) ?>"><div class="form-grid"><label>Office name<input name="office_name" value="<?= e($office['name']??'Head Office') ?>" required></label><label>Latitude<input type="number" step="0.0000001" name="office_latitude" value="<?= e($office['latitude']??'') ?>" required></label><label>Longitude<input type="number" step="0.0000001" name="office_longitude" value="<?= e($office['longitude']??'') ?>" required></label><label>Geofence radius (metres)<input type="number" name="radius_metres" min="10" value="<?= e($office['radius_metres']??200) ?>" required></label></div><?php if(!$office):?><div class="inline-alert info"><i class="fa-solid fa-circle-info"></i> Enter the real office coordinates before enabling attendance geofencing.</div><?php endif;?></section>
<section class="panel settings-section" id="attendance-rules"><div class="panel-head"><div><h2>Attendance & late rules</h2><p>Configurable shift deductions and validation</p></div></div><?php if($rules):?><input type="hidden" name="rule_id" value="<?= $rules['id'] ?>"><div class="form-grid"><label>Grace minutes<input type="number" name="grace_minutes" min="0" value="<?= e($rules['grace_minutes']) ?>"></label><label>Half-day minutes<input type="number" name="half_day_minutes" min="1" value="<?= e($rules['half_day_minutes']) ?>"></label><label>Full-day minutes<input type="number" name="full_day_minutes" min="1" value="<?= e($rules['full_day_minutes']) ?>"></label><label>Overtime after minutes<input type="number" name="overtime_after_minutes" min="1" value="<?= e($rules['overtime_after_minutes']) ?>"></label><label>Maximum location accuracy (m)<input type="number" name="max_accuracy_metres" min="10" value="<?= e($rules['max_accuracy_metres']) ?>"></label><label>Late fine rule<select name="late_fine_type"><?php foreach(['none'=>'No deduction','occurrence'=>'Per late occurrence','minute'=>'Per late minute','late_count_half_day'=>'Configured count = half day'] as $key=>$label):?><option value="<?= e($key) ?>" <?= $rules['late_fine_type']===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach;?></select></label><label>Late fine amount<input type="number" step="0.01" min="0" name="late_fine_amount" value="<?= e($rules['late_fine_amount']) ?>"></label><label>Max monthly late deduction<input type="number" step="0.01" min="0" name="max_monthly_late_deduction" value="<?= e($rules['max_monthly_late_deduction']) ?>"></label><label class="check-label"><input type="checkbox" name="require_geofence" <?= $rules['require_geofence']?'checked':'' ?>> Require geofence</label><label class="check-label"><input type="checkbox" name="require_photo" <?= $rules['require_photo']?'checked':'' ?>> Require photo</label></div><?php endif;?></section>
<div class="sticky-save"><span><i class="fa-solid fa-circle-info"></i> Changes apply to future calculations and punches.</span><button class="button button-primary"><i class="fa-solid fa-floppy-disk"></i> Save settings</button></div></div></div></form>
<section class="panel settings-section backup-section" id="backups"><div class="panel-head"><div><h2>Database backups</h2><p>Manual SQL snapshots stored outside the public directory</p></div><form method="post" action="<?= url('settings/backup') ?>"><?= csrf_field() ?><button class="button button-primary"><i class="fa-solid fa-database"></i> Create backup</button></form></div><div class="table-scroll"><table class="data-table"><thead><tr><th>File</th><th>Size</th><th>Status</th><th>Created by</th><th>Created</th></tr></thead><tbody><?php foreach($backups as $backup):?><tr><td><strong><?= e($backup['filename']) ?></strong></td><td><?= number_format($backup['file_size']/1024,1) ?> KB</td><td><span class="status-badge <?= status_class($backup['status']) ?>"><?= e($backup['status']) ?></span></td><td><?= e($backup['name']?:'System') ?></td><td><?= e(date('d M Y, g:i A',strtotime($backup['created_at']))) ?></td></tr><?php endforeach;?><?php if(!$backups):?><tr><td colspan="5"><div class="empty-inline">No manual backups yet.</div></td></tr><?php endif;?></tbody></table></div></section>
